import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"Configuration troubleshooting: locate the failing layer","description":"Diagnose startup, dependency, login, browser, repository, and runtime-setting failures by symptom and verify each fix with a concrete result.","frontmatter":{"page_id":"configuration-troubleshooting","title":"Configuration troubleshooting: locate the failing layer","description":"Diagnose startup, dependency, login, browser, repository, and runtime-setting failures by symptom and verify each fix with a concrete result."},"headers":[],"relativePath":"en/configuration/troubleshooting.md","filePath":"en/configuration/troubleshooting.md","lastUpdated":1786289447000}'),r={name:"en/configuration/troubleshooting.md"};function s(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="configuration-troubleshooting-locate-the-failing-layer" tabindex="-1">Configuration troubleshooting: locate the failing layer <a class="header-anchor" href="#configuration-troubleshooting-locate-the-failing-layer" aria-label="Permalink to &quot;Configuration troubleshooting: locate the failing layer&quot;">​</a></h1><p>Start by identifying the failing layer: process creation, startup lifespan, an external dependency, request security, repository authorization, or a runtime override. Do not treat one <code>ok</code> from <code>/health</code> as the whole diagnosis.</p><h2 id="the-api-exits-before-showing-a-listening-address" tabindex="-1">The API exits before showing a listening address <a class="header-anchor" href="#the-api-exits-before-showing-a-listening-address" aria-label="Permalink to &quot;The API exits before showing a listening address&quot;">​</a></h2><h3 id="symptom" tabindex="-1">Symptom <a class="header-anchor" href="#symptom" aria-label="Permalink to &quot;Symptom&quot;">​</a></h3><p>The error names <code>SECRET_KEY</code>, <code>ENCRYPTION_KEY</code>, <code>MCP_KEY_PEPPER</code>, secure Cookies, <code>OPAQUE_SERVER_SETUP</code>, or the development local-path switch.</p><h3 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h3><ol><li>Make the first three secrets at least 32 characters long, distinct, and different from <code>change-me</code> and <code>replace-me</code>.</li><li>If the environment is <code>prod</code> or <code>production</code>, set <code>SESSION_COOKIE_SECURE=true</code>.</li><li>Set <code>SESSION_COOKIE_SAMESITE</code> to <code>lax</code>, <code>strict</code>, or <code>none</code>.</li><li>Production requires stable <code>OPAQUE_SERVER_SETUP</code> material and rejects <code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS=true</code>.</li></ol><h3 id="successful-result" tabindex="-1">Successful result <a class="header-anchor" href="#successful-result" aria-label="Permalink to &quot;Successful result&quot;">​</a></h3><p>Application creation completes and enters the startup lifespan without the same validation error. Continue to check the database: passing settings validation does not mean lifespan startup has completed.</p><h2 id="application-creation-succeeds-but-lifespan-startup-fails" tabindex="-1">Application creation succeeds, but lifespan startup fails <a class="header-anchor" href="#application-creation-succeeds-but-lifespan-startup-fails" aria-label="Permalink to &quot;Application creation succeeds, but lifespan startup fails&quot;">​</a></h2><h3 id="symptom-1" tabindex="-1">Symptom <a class="header-anchor" href="#symptom-1" aria-label="Permalink to &quot;Symptom&quot;">​</a></h3><p>The service exits while connecting to the database, reading system settings, or initializing login material, before it reaches a stable listening state.</p><h3 id="checks-1" tabindex="-1">Checks <a class="header-anchor" href="#checks-1" aria-label="Permalink to &quot;Checks&quot;">​</a></h3><ol><li>Check the driver, host, port, database name, and credentials in <code>DATABASE_URL</code>.</li><li>Confirm that the database is running and the account can read, write, and use the upgraded schema.</li><li>In an environment with dependencies already installed, run <code>uv run ershu-db heads</code>. Current source should report migration head <code>0002</code>.</li><li>If an upgrade is needed, run <code>uv run ershu-db upgrade head</code>, then restart the API.</li></ol><p>There is one known source conflict: the PostgreSQL integration assertion in <code>core/tests/test_migrations_postgres.py</code> still expects <code>0001</code>, while the latest migration is <code>0002</code>. Diagnose the schema version from the migration directory and <code>ershu-db heads</code>, not that stale assertion.</p><h3 id="successful-result-1" tabindex="-1">Successful result <a class="header-anchor" href="#successful-result-1" aria-label="Permalink to &quot;Successful result&quot;">​</a></h3><p>The API remains running, <code>GET /health</code> returns <code>{&quot;status&quot;:&quot;ok&quot;}</code>, and the process no longer exits during lifespan initialization.</p><h2 id="health-is-healthy-but-dependency-status-is-degraded" tabindex="-1"><code>/health</code> is healthy, but dependency status is <code>degraded</code> <a class="header-anchor" href="#health-is-healthy-but-dependency-status-is-degraded" aria-label="Permalink to &quot;`/health` is healthy, but dependency status is `degraded`&quot;">​</a></h2><p><code>GET /health</code> and <code>GET /api/v1/health</code> only report process liveness. <code>GET /api/v1/health/dependencies</code> checks the database and Milvus, and still uses HTTP 200 when one is degraded.</p><table tabindex="0"><thead><tr><th>Response field</th><th>Meaning</th><th>Next action</th></tr></thead><tbody><tr><td><code>database.ok: false</code></td><td><code>select 1</code> failed</td><td>Check <code>DATABASE_URL</code>, networking, credentials, and database state</td></tr><tr><td><code>milvus.ok: false</code></td><td>The Milvus connection or query failed</td><td>Check the URI, token, database name, and service state</td></tr><tr><td><code>status: degraded</code></td><td>At least one of the two checks failed</td><td>Repair it and repeat the request until both <code>ok</code> fields are <code>true</code></td></tr></tbody></table><p>This endpoint does not check Redis, Worker, or model channels and is not proof that the whole system is ready.</p><h2 id="login-returns-503-while-dependency-health-is-normal" tabindex="-1">Login returns 503 while dependency health is normal <a class="header-anchor" href="#login-returns-503-while-dependency-health-is-normal" aria-label="Permalink to &quot;Login returns 503 while dependency health is normal&quot;">​</a></h2><p>Login rate limiting connects to <code>REDIS_URL</code> on first use. An empty URL, missing client package, connection failure, or invalid counter value is mapped to 503.</p><p>After checking the Redis address and network, make a real login attempt. Success means login no longer fails because its rate-limit store is unavailable; the dependency-health response does not change. Eight failed attempts inside the current five-minute window still trigger normal rate limiting.</p><h2 id="production-reports-that-https-is-required" tabindex="-1">Production reports that HTTPS is required <a class="header-anchor" href="#production-reports-that-https-is-required" aria-label="Permalink to &quot;Production reports that HTTPS is required&quot;">​</a></h2><p>In production, the API rejects requests under <code>/api/</code> and <code>/mcp</code> when their scheme is not HTTPS. If the browser uses HTTPS but the backend still sees HTTP:</p><ol><li>Make sure the reverse proxy sends the original scheme in its forwarded headers.</li><li>Confirm <code>PROXY_HEADERS=true</code>.</li><li>Add only the actual proxy addresses to <code>FORWARDED_ALLOW_IPS</code>.</li></ol><p>After the fix, the same HTTPS request should reach its route, while direct HTTP should still be rejected.</p><h2 id="a-browser-write-returns-403" tabindex="-1">A browser write returns 403 <a class="header-anchor" href="#a-browser-write-returns-403" aria-label="Permalink to &quot;A browser write returns 403&quot;">​</a></h2><p>Read the error body first:</p><ul><li><code>Cross-site request blocked</code> means <code>Origin</code> or <code>Referer</code> is neither the current site nor an entry in <code>CORS_ORIGINS</code>;</li><li><code>csrf_invalid</code> means the <code>X-Ershu-CSRF</code> header is missing, differs from the CSRF Cookie, or has an invalid signature.</li></ul><p>Read requests do not trigger this write protection. A Cookie-authenticated write must pass CSRF validation; when the browser supplies <code>Origin</code> or <code>Referer</code>, that origin must also be allowed. A Bearer request does not use Cookie identity and therefore does not need CSRF, but it still needs a valid token.</p><p>After the fix, a write from an allowed origin with matching CSRF header and Cookie should reach the business route. Deliberately removing the header should still return 403.</p><h2 id="a-remote-repository-url-is-rejected" tabindex="-1">A remote repository URL is rejected <a class="header-anchor" href="#a-remote-repository-url-is-rejected" aria-label="Permalink to &quot;A remote repository URL is rejected&quot;">​</a></h2><p>The error normally identifies the category:</p><table tabindex="0"><thead><tr><th>Error direction</th><th>Check</th></tr></thead><tbody><tr><td>Protocol not accepted</td><td>Use HTTPS, SSH, or SCP-like syntax by default; do not open an insecure protocol merely for convenience</td></tr><tr><td>Host not allowed</td><td>A non-empty <code>GIT_ALLOWED_HOSTS</code> must match the exact host or a wildcard rule</td></tr><tr><td>Host cannot resolve</td><td>Check DNS and spelling</td></tr><tr><td>Host resolves to a blocked address</td><td>Private, loopback, and link-local addresses are blocked by default; an internal Git service needs an exact allowlist entry, while loopback remains blocked</td></tr></tbody></table><p>After changing the host list at runtime, reread the administrator settings and confirm the target item&#39;s <code>source</code> and <code>value</code>. Then begin a new clone or fetch; an earlier failed operation is not replayed automatically.</p><h2 id="a-local-repository-path-is-not-trusted" tabindex="-1">A local repository path is not trusted <a class="header-anchor" href="#a-local-repository-path-is-not-trusted" aria-label="Permalink to &quot;A local repository path is not trusted&quot;">​</a></h2><p>A valid path is inside the managed cache, covered by <code>TRUSTED_LOCAL_PATHS</code>, or contains <code>.git</code> itself. Relative paths resolve from the service process&#39;s current working directory, so an explicit absolute path is clearer in deployment.</p><p><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code> is only a non-production fallback when there is no trusted-path list. Production cannot use it. A successful fix lets a new workspace open without <code>Repository local_path is not trusted</code>, without granting access to the whole filesystem.</p><h2 id="an-administrator-change-does-not-take-effect" tabindex="-1">An administrator change does not take effect <a class="header-anchor" href="#an-administrator-change-does-not-take-effect" aria-label="Permalink to &quot;An administrator change does not take effect&quot;">​</a></h2><p>Use this sequence:</p><ol><li>Find the target item in <code>GET /api/v1/admin/system-settings</code>.</li><li>If it is absent, it is not runtime-overridable. Change its environment value and restart the affected process.</li><li>If <code>source</code> is <code>environment</code>, no database override exists; check whether the update request succeeded.</li><li>If <code>source</code> is <code>database</code>, confirm <code>value</code> is correct and remember that it normally affects only later operations.</li><li>API instances refresh at startup and every 30 seconds. Worker has its own refresh points, so API timing does not establish Worker state.</li></ol><p>The administration service rejects unknown names, wrong types, and out-of-range values. Do not bypass validation by writing JSON directly into the database; a bad row can make every periodic refresh log an error.</p><h2 id="development-api-documentation-disappears" tabindex="-1">Development API documentation disappears <a class="header-anchor" href="#development-api-documentation-disappears" aria-label="Permalink to &quot;Development API documentation disappears&quot;">​</a></h2><p><code>/docs</code> and <code>/redoc</code> are enabled only when <code>ENVIRONMENT</code> is exactly the lowercase word <code>development</code>. <code>Development</code>, <code>dev</code>, and production values all disable them. Restart the API after changing it because environment settings are cached.</p><h2 id="dependencies-cannot-be-installed-from-public-sources" tabindex="-1">Dependencies cannot be installed from public sources <a class="header-anchor" href="#dependencies-cannot-be-installed-from-public-sources" aria-label="Permalink to &quot;Dependencies cannot be installed from public sources&quot;">​</a></h2><p>The current API <code>pyproject.toml</code> pins Core to a private Gitea commit. Without read access to that source, dependency resolution failure is a current distribution constraint, not something that can be repaired by inventing a public package address.</p><p>Use a prepared internal workspace or wait for a public distribution path. Do not change remote addresses without authorization, fabricate a public dependency, or place private credentials in an example.</p><h2 id="source-locations" tabindex="-1">Source locations <a class="header-anchor" href="#source-locations" aria-label="Permalink to &quot;Source locations&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>: settings and security validation errors.</li><li><code>core/src/ershu/db/migrations.py</code> and <code>core/alembic/versions/</code>: migration entry point and current revisions.</li><li><code>core/tests/test_migrations_postgres.py</code>: the known assertion that still expects the old revision.</li><li><code>api/src/ershu/api_main.py</code>: creation, lifespan startup, HTTPS, origin, and CSRF handling.</li><li><code>api/src/ershu/api/routes/health.py</code> and <code>api/src/ershu/api/database.py</code>: liveness and dependency checks.</li><li><code>api/src/ershu/api/services/auth/login_limits.py</code>: Redis connection and the eight-failures-in-five-minutes limit.</li><li><code>core/src/ershu/services/repositories/git_url_security.py</code>: remote host rejection reasons.</li><li><code>core/src/ershu/tools/readonly_repository/workspace.py</code>: local path trust rules.</li><li><code>api/src/ershu/api/services/system_settings.py</code>: runtime setting sources, validation, and reset.</li><li><code>api/pyproject.toml</code>: the currently pinned private Core source.</li></ul>',51)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
